  test("handles an empty task list", async () => {
    const result = await run({ tasks: [] });
    expect(result.exitCode).toBe(0);
    expect(JSON.parse(result.stdout)).toEqual({
      order: [],
      layers: [],
      earliest: {},
      totalDuration: 0,
      criticalPath: [],
    });
  });

  test("reports a deterministic concrete cycle", async () => {
    const result = await run({
      tasks: [
        { id: "c", duration: 1, dependsOn: ["a"] },
        { id: "b", duration: 1, dependsOn: ["c"] },
        { id: "a", duration: 1, dependsOn: ["b"] },
      ],
    });
    expect(result.exitCode).not.toBe(0);
    expect(result.stdout).toBe("");
    expect(result.stderr).toContain("dependency cycle: a -> b -> c -> a");
  });

  test("rejects invalid dependencies", async () => {
    const duplicate = await run({
      tasks: [{ id: "a", duration: 1, dependsOn: ["b", "b"] }, { id: "b", duration: 1 }],
    });
    expect(duplicate.exitCode).not.toBe(0);
    expect(duplicate.stderr).toContain("duplicate id: b");

    const unknown = await run({ tasks: [{ id: "a", duration: 1, dependsOn: ["missing"] }] });
    expect(unknown.exitCode).not.toBe(0);
    expect(unknown.stderr).toContain("unknown task: missing");
  });
});
# Dependency Planner

A dependency-free TypeScript CLI for Bun that validates a task graph and emits a deterministic execution plan.

## Usage

```sh
bun run src/cli.ts plan INPUT.json
```

Input has the form:

```json
{
  "tasks": [
    { "id": "lint", "duration": 1 },
    { "id": "build", "duration": 3, "dependsOn": ["lint"] }
  ]
}
```

Successful runs print one JSON object containing the lexicographical topological `order`, concurrent `layers`, earliest start/finish times, total duration, and a deterministically selected critical path. Invalid input and dependency cycles produce a useful error on stderr and a non-zero exit code.

## Test

```sh
bun test
```
